INSERT INTO `meeting_notes` (`id`, `item_id`, `tanggal`, `topic`, `leader`, `attendees`, `discussion_summary`, `action_items_json`, `status`, `plant_health`, `critical_issue`, `operational_impact`, `management_decision`, `created_at`, `updated_at`) VALUES
(1, 'MEET-001', '2026-09-08', 'Evaluasi Kesiapan Alat Berat & Pencapaian Physical Availability (PA) Week 1', 'Hariadi (GM Plant)', 'Andi Herwan (Planner), Brayen (Logistic), M. Nur Salam (Direksi), Foreman Mekanik', 'Pembahasan evaluasi PA armada Excavator CAT 330 GX dan Bulldozer SEM 822D di site KBCT. Target PA minimum 88% saat ini tercapai 91%. Perhatian khusus pada unit DZ-007 yang mengalami overheat pada torque converter.', '[{"task":"Inspeksi oil cooler DZ-007","pic":"Tim Mekanik","deadline":"2026-09-10"},{"task":"Follow up order seal kit cylinder arm","pic":"Brayen (Logistic)","deadline":"2026-09-11"}]', 'Open', 'OPTIMAL (91% PA)', 'Overheat berkala pada DZ-007 saat dorong overburden berat', 'Potensi delay ripping & penataan disposal', 'Segera lakukan flushing system pendingin DZ-007 dan alokasikan unit cadangan DZ-008 untuk penataan disposal utama.', '2026-09-20 06:58:02', '2026-09-20 06:58:02'),
(2, 'MEET-002', '2026-09-11', 'Rapat Koordinasi Kebutuhan Suku Cadang & Service 1000H EX-302', 'Andi Herwan (PMC / Planner)', 'Brayen (Logistics), Tim Mekanik Shift, Supervisor Tambang', 'Penjadwalan Service berkala 1000 Jam untuk EX-302 (SANY SY330H). Konfirmasi ketersediaan filter oli mesin, filter solar separator, dan oli hydraulic Tellus S2 68 di gudang utama.', '[{"task":"Persiapan part service 1000H","pic":"Logistik","deadline":"2026-09-12"},{"task":"Eksekusi service pada jam standby pit","pic":"Mekanik Shift 1","deadline":"2026-09-13"}]', 'Scheduled', 'OPTIMAL', 'Stok oli hydraulic di gudang menipis (sisa 2 drum)', 'Perlu PR darurat untuk 10 drum oli hidrolik', 'PO darurat untuk 10 drum oli Shell Tellus disetujui Direksi. Eksekusi service EX-302 dijadwalkan Minggu pagi pukul 07:00.', '2026-09-20 06:58:02', '2026-09-20 06:58:02'),
(3, 'MEET-003', '2026-09-13', 'Audit Keselamatan Kerja (K3) Bengkel Plant & Kalibrasi Alat Khusus', 'M. Nur Salam (Direksi / HSE)', 'Hariadi (GM), Andi Herwan, Seluruh Mekanik & Helper', 'Pemeriksaan kepatuhan APD mekanik, housekeeping area pencucian part workshop, penataan drum oli bekas, dan kalibrasi torque wrench 800 Nm.', '[{"task":"Pembersihan oli rembesan di bay 2","pic":"Helper Workshop","deadline":"2026-09-14"},{"task":"Pemberian sertifikat kalibrasi tools","pic":"Planner","deadline":"2026-09-15"}]', 'Closed', 'SAFE & COMPLIANT', 'SOP pengangkatan beban hoist crane perlu diperbarui', 'Nir-kecelakaan kerja (Zero LTI) selama 420 hari', 'Terapkan daily safety talk 5 menit sebelum briefing shift pagi dan ganti sling web hoist yang telah aus.', '2026-09-20 06:58:02', '2026-09-20 06:58:02');
